// Code generated by analysis/schema/rule/emitlaw; DO NOT EDIT.
//
// These are the laws every rule declaration owes by construction. They are
// derived from the declaration itself, so a family authors beside them only
// the laws that state what its fold means.

package program

import (
	"testing"

	schemaapi "github.com/wippyai/go-lua/analysis/schema"
	axismember "github.com/wippyai/go-lua/analysis/schema/axis/member"
	emitlaw "github.com/wippyai/go-lua/analysis/schema/rule/emitlaw"
	ruleprogram "github.com/wippyai/go-lua/analysis/schema/rule/program"
	axiscatalog "github.com/wippyai/go-lua/domain/heap"
)

// closedAllocationGeometry is the whole geometry the declaration carries, in the one
// canonical form every emitted law suite states a declaration in. It is total
// over the cold ABI: every join clause, contract term, fold argument, output
// clause, carry, and transport row appears on exactly one line.
const closedAllocationGeometry = `operand              semantic/operand/heap/allocation-closed
candidate            relation=axis/heap:heap/closed-allocation/candidates issued-row=-
join[0].read         form=exact input=0 axis=axis/heap point-bound=bound
join[0].relation     axis/heap:heap/closed-allocation/predecessors
join[0].key          axis/heap:heap/closed-allocation/predecessor-key
join[0].predicate    -
join[0].selection    -
join[0].parent       -
join[0].sources      candidate
join[0].contract     order=canonical sparse=explicit on-opaque=refuse multiplicity=one denominator=-
join[1].read         form=summary input=1 axis=axis/value point-bound=self
join[1].relation     axis/value:value/closed-allocation/operands
join[1].key          axis/value:value/closed-allocation/operand-key
join[1].predicate    -
join[1].selection    -
join[1].parent       -
join[1].sources      candidate
join[1].contract     order=canonical sparse=explicit on-opaque=refuse multiplicity=many denominator=denominator/coordinates/value
observation          points=2 reads=2
observation[0]       read=0 point=0
observation[1]       read=1 point=1
observation.carry    point=0
carry                mode=transform input=0 transform=axis/heap:transform/heap/allocation-closed output=scalar(0,0)
fold.reducer         axis/heap:heap/reducer/closed
fold.inputs          join 0, join 1
output[0]            mode=exact value-slot=0 route=- column=axis/heap:heap/facts destination=axis/heap:heap/closed-allocation/coordinate
transport            none
`

// TestClosedAllocationGeometryIsTheOneItsLawSuiteWasEmittedFrom holds the declaration to the
// geometry above. The rendering is checked in beside the declaration and the
// freshness law re-derives it, so a declaration that moves without
// regeneration fails the build and one that moves with it is a reviewable
// diff of exactly what changed.
func TestClosedAllocationGeometryIsTheOneItsLawSuiteWasEmittedFrom(t *testing.T) {
	if got := emitlaw.Canonical(ClosedAllocation()); got != closedAllocationGeometry {
		t.Fatalf("declared geometry has moved away from its law suite:\ngot:\n%s\nwant:\n%s", got, closedAllocationGeometry)
	}
}

// TestClosedAllocationAgreesWithTheCallShapeOfTheReducerItNames is the one structural law a
// Program cannot settle alone. Check sees only the declaration, so a fold that
// hands its reducer a join the owner does not take is well formed in isolation
// and wrong against the row it names. The reducer's call shape is the owner
// axis's statement, and this law is where the two are held together.
func TestClosedAllocationAgreesWithTheCallShapeOfTheReducerItNames(t *testing.T) {
	declaration := ClosedAllocation()
	if problem, valid := declaration.Check(); !valid {
		t.Fatalf("declaration is malformed: %+v", problem)
	}
	reducer, reducerOK := axiscatalog.AxisMemberCatalog().Reducer(schemaapi.Key("heap/reducer/closed"))
	if !reducerOK {
		t.Fatal("the reducer axis publishes no reducer named heap/reducer/closed")
	}
	if problem, valid := declaration.CheckAgainst(reducer); !valid {
		t.Fatalf("declaration disagrees with its reducer's call shape: %+v", problem)
	}
}

// TestClosedAllocationIsHandedOutFresh states that the accessor yields a declaration a caller
// owns. Every law that probes a malformed edit mutates what it is handed, and a
// declaration backed by shared storage would carry one law's edit into the next
// reader - including the composition that seals it.
func TestClosedAllocationIsHandedOutFresh(t *testing.T) {
	first := ClosedAllocation()
	first.OperandRole = "law/mutation/operand"
	for index := range first.Joins {
		first.Joins[index].Relation.Member = "law/mutation/relation"
		for source := range first.Joins[index].Sources {
			first.Joins[index].Sources[source] = ruleprogram.PriorSource(0)
		}
	}
	for index := range first.Fold.Outputs {
		first.Fold.Outputs[index].Destination.Member = "law/mutation/destination"
	}
	for index := range first.Fold.Inputs {
		first.Fold.Inputs[index] = ruleprogram.JoinRef(0)
	}
	if first.Carry != nil {
		first.Carry.Mode = ruleprogram.CarryModeInvalid
	}
	if first.Activation != nil {
		for index := range first.Activation.Transport {
			first.Activation.Transport[index].Exported = !first.Activation.Transport[index].Exported
		}
	}
	if got := emitlaw.Canonical(ClosedAllocation()); got != closedAllocationGeometry {
		t.Fatalf("a caller's edits reached the next declaration:\n%s", got)
	}
}

// closedAllocationIdentity is the rule identity this declaration is sealed under.
const closedAllocationIdentity = `rule                 heap-closed
lane                 mounted
writes               heap
owner                heap
semantic             semantic/rule/heap/allocation-closed
role[0]              semantic/operand/heap/allocation-closed
role[1]              semantic/transform/heap/allocation-closed
issue[0]             occurrence=occurrence/allocation-closed form=program-form/local-successor requirement=program-requirement/unrestricted
`

// TestClosedAllocationRuleEntryIsTheSealedDeclaration holds the rule entry to its identity, to
// the declaration this suite was emitted from, and to handing out issuance a
// caller owns. An entry that shared its issuance storage would let one reader's
// edit become every later reader's declaration.
func TestClosedAllocationRuleEntryIsTheSealedDeclaration(t *testing.T) {
	entry := RuleEntry()
	if got := emitlaw.CanonicalEntry(entry); got != closedAllocationIdentity {
		t.Fatalf("rule identity has moved away from its law suite:\ngot:\n%s\nwant:\n%s", got, closedAllocationIdentity)
	}
	if got := emitlaw.Canonical(entry.Program); got != closedAllocationGeometry {
		t.Fatalf("the entry carries a different declaration than the one it is sealed over:\n%s", got)
	}
	for index := range entry.Issues {
		entry.Issues[index].Occurrence = "law/mutation/occurrence"
		entry.Issues[index].Form = "law/mutation/form"
		entry.Issues[index].Requirement = "law/mutation/requirement"
	}
	for index := range entry.Roles {
		entry.Roles[index] = "law/mutation/role"
	}
	if got := emitlaw.CanonicalEntry(RuleEntry()); got != closedAllocationIdentity {
		t.Fatalf("a caller's edits reached the next rule entry:\n%s", got)
	}
}

// TestClosedAllocationRefusesEveryStructuralMutation is the negative half of the declaration's
// structure: for every term the cold ABI carries, the edit that removes or
// corrupts it, and the verdict Check gives it. The table is total over the
// declaration rather than a sample of it, which is the whole reason it is
// derived: an authored suite states the three edits its author thought of.
//
// Each verdict is the one this suite's emitter watched Check give while
// deriving. Check runs for real here, so a checker that stops refusing an edit
// fails this law, and a checker that refuses it differently shows up as a
// regeneration diff.
func TestClosedAllocationRefusesEveryStructuralMutation(t *testing.T) {
	for _, law := range []struct {
		mutation string
		apply    func(declaration *ruleprogram.Program)
		kind     ruleprogram.ProblemKind
		join     int
		input    int
		output   int
	}{
		{mutation: "the operand role is cleared", apply: func(declaration *ruleprogram.Program) { declaration.OperandRole = "" }, kind: ruleprogram.ProblemOperand},
		{mutation: "the candidate provider is cleared", apply: func(declaration *ruleprogram.Program) { declaration.Candidate = axismember.CandidateRef{} }, kind: ruleprogram.ProblemCandidate},
		{mutation: "the candidate relation loses its member", apply: func(declaration *ruleprogram.Program) { declaration.Candidate.AxisRelation.Member = "" }, kind: ruleprogram.ProblemCandidate},
		{mutation: "join 0 loses its relation", apply: func(declaration *ruleprogram.Program) { declaration.Joins[0].Relation.Member = "" }, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its key projection", apply: func(declaration *ruleprogram.Program) { declaration.Joins[0].Key.Member = "" }, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its read axis", apply: func(declaration *ruleprogram.Program) { declaration.Joins[0].Read.Axis = ruleprogram.AxisRef{} }, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its read form", apply: func(declaration *ruleprogram.Program) { declaration.Joins[0].Read.Form = ruleprogram.ReadFormInvalid }, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its point-bound disposition", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.PointBound = ruleprogram.PointBoundInvalid
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its declared cell order", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.Contract.Order = ruleprogram.OrderInvalid
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its sparsity", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.Contract.Sparse = ruleprogram.SparseInvalid
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its opaque-evidence disposition", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.Contract.OnOpaque = ruleprogram.OnOpaqueInvalid
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 loses its multiplicity", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.Contract.Multiplicity = ruleprogram.MultiplicityInvalid
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 repeats one of its sources", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Sources = append(declaration.Joins[0].Sources, declaration.Joins[0].Sources[0])
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "join 0 sources a result that is not yet produced", apply: func(declaration *ruleprogram.Program) { declaration.Joins[0].Sources[0] = ruleprogram.PriorSource(0) }, kind: ruleprogram.ProblemJoin},
		{mutation: "join 1 loses its relation", apply: func(declaration *ruleprogram.Program) { declaration.Joins[1].Relation.Member = "" }, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its key projection", apply: func(declaration *ruleprogram.Program) { declaration.Joins[1].Key.Member = "" }, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its read axis", apply: func(declaration *ruleprogram.Program) { declaration.Joins[1].Read.Axis = ruleprogram.AxisRef{} }, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its read form", apply: func(declaration *ruleprogram.Program) { declaration.Joins[1].Read.Form = ruleprogram.ReadFormInvalid }, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its point-bound disposition", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.PointBound = ruleprogram.PointBoundInvalid
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its declared cell order", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.Contract.Order = ruleprogram.OrderInvalid
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its sparsity", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.Contract.Sparse = ruleprogram.SparseInvalid
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its opaque-evidence disposition", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.Contract.OnOpaque = ruleprogram.OnOpaqueInvalid
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 loses its multiplicity", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.Contract.Multiplicity = ruleprogram.MultiplicityInvalid
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 repeats one of its sources", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Sources = append(declaration.Joins[1].Sources, declaration.Joins[1].Sources[0])
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "join 1 sources a result that is not yet produced", apply: func(declaration *ruleprogram.Program) { declaration.Joins[1].Sources[0] = ruleprogram.PriorSource(1) }, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "the fold names no reducer", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Reducer.Member = "" }, kind: ruleprogram.ProblemFold},
		{mutation: "the fold consumes nothing", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Inputs = nil }, kind: ruleprogram.ProblemInput},
		{mutation: "the fold publishes nothing", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs = nil }, kind: ruleprogram.ProblemOutput},
		{mutation: "the fold consumes a join the declaration does not carry", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Inputs[0] = ruleprogram.JoinRef(2) }, kind: ruleprogram.ProblemInput},
		{mutation: "the fold stops consuming its argument at position 0", apply: func(declaration *ruleprogram.Program) {
			declaration.Fold.Inputs = append(declaration.Fold.Inputs[:0:0], declaration.Fold.Inputs[1:]...)
		}, kind: ruleprogram.ProblemJoin},
		{mutation: "the fold stops consuming its argument at position 1", apply: func(declaration *ruleprogram.Program) {
			declaration.Fold.Inputs = append(declaration.Fold.Inputs[:1:1], declaration.Fold.Inputs[2:]...)
		}, kind: ruleprogram.ProblemJoin, join: 1},
		{mutation: "output 0 loses its destination projection", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs[0].Destination.Member = "" }, kind: ruleprogram.ProblemOutput},
		{mutation: "output 0 loses its declared column", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs[0].Column.Key = "" }, kind: ruleprogram.ProblemOutput},
		{mutation: "output 0 loses its publication mode", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs[0].Mode = ruleprogram.ModeInvalid }, kind: ruleprogram.ProblemOutput},
		{mutation: "output 0 publishes into a value slot the fold does not have", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs[0].ValueSlot = 1 }, kind: ruleprogram.ProblemOutput},
		{mutation: "output 0 claims a route it does not publish through", apply: func(declaration *ruleprogram.Program) { declaration.Fold.Outputs[0].RouteJoinPresent = true }, kind: ruleprogram.ProblemOutput},
		{mutation: "the carry loses its disposition", apply: func(declaration *ruleprogram.Program) { declaration.Carry.Mode = ruleprogram.CarryModeInvalid }, kind: ruleprogram.ProblemCarry},
		{mutation: "the carry names an input port the declaration does not open", apply: func(declaration *ruleprogram.Program) { declaration.Carry.Input = ruleprogram.InputRef(3) }, kind: ruleprogram.ProblemInput},
		{mutation: "the transforming carry loses its transform", apply: func(declaration *ruleprogram.Program) { declaration.Carry.Transform.Member = "" }, kind: ruleprogram.ProblemCarry},
	} {
		declaration := ClosedAllocation().Clone()
		law.apply(&declaration)
		problem, valid := declaration.Check()
		if valid {
			t.Fatalf("Check admits a declaration where %s", law.mutation)
		}
		if problem.Kind != law.kind || problem.Join != law.join || problem.Input != law.input || problem.Output != law.output {
			t.Fatalf("where %s, Check refused with %+v", law.mutation, problem)
		}
	}
}

// TestClosedAllocationAdmitsTheseEditsAtDeclarationLevel states where Check's authority ends.
// Check is data-local: it seals ordering, the normal forms, fold connectivity,
// and output arity without reopening any owner schema. The edits below are
// therefore well formed to it and are refused, if at all, by the seal that
// resolves them against the complete catalog.
//
// This law exists so that boundary is on record rather than implied by absence.
// An edit that starts being refused here is a checker that grew, and it shows
// up as a regeneration diff instead of passing unnoticed.
func TestClosedAllocationAdmitsTheseEditsAtDeclarationLevel(t *testing.T) {
	for _, law := range []struct {
		mutation string
		apply    func(declaration *ruleprogram.Program)
	}{
		{mutation: "join 0 is unbounded", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[0].Read.Contract.Multiplicity = ruleprogram.MultiplicityMany
		}},
		{mutation: "join 1 is unbounded", apply: func(declaration *ruleprogram.Program) {
			declaration.Joins[1].Read.Contract.Multiplicity = ruleprogram.MultiplicityMany
		}},
	} {
		declaration := ClosedAllocation().Clone()
		law.apply(&declaration)
		if problem, valid := declaration.Check(); !valid {
			t.Fatalf("Check has grown to refuse a declaration where %s: %+v", law.mutation, problem)
		}
	}
}
